# Column definitions
TP_COLS = ["Index","SS / Module","Feature","Test Case Name","Test Description","Speed","Mode",
           "Memory Start Offset","Memory End Offset","Remarks","Test Steps / Procedure",
           "Impacted Registers","Validation / Acceptance Criteria","Code Generation"]
MD_COLS = ["Index","Test Case Name","Meta Test Description","Meta Test Steps / Procedure",
           "Meta Impacted Registers","Meta Validation / Acceptance Criteria",
           "Meta Headers","Meta Macros","Meta Arrays"]

# Styles
HEADER_FONT = Font(name='Calibri', bold=True, color='FFFFFF', size=11)
HEADER_FILL = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')
WRAP = Alignment(wrap_text=True, vertical='top')
THIN_BORDER = Border(
    left=Side(style='thin'), right=Side(style='thin'),
    top=Side(style='thin'), bottom=Side(style='thin'))

def auto_width(ws, max_w=60):
    for col in ws.columns:
        mx = 0
        cl = get_column_letter(col[0].column)
        for cell in col:
            if cell.value:
                lines = str(cell.value).split('\n')
                for l in lines:
                    mx = max(mx, len(l))
        ws.column_dimensions[cl].width = min(max(mx + 2, 12), max_w)

def build():
    wb = Workbook()
    # TestPlan sheet
    ws_tp = wb.active
    ws_tp.title = "TestPlan"
    ws_tp.append(TP_COLS)
    for r in DATA:
        ws_tp.append([
            r["index"], r["ss_module"], r["feature"], r["test_case_name"],
            r["test_description"], r["speed"], r["mode"],
            r["memory_offset"], "", r["remarks"], r["test_steps"],
            r["impacted_registers"], r["validation_criteria"], ""
        ])
    # MetaData sheet
    ws_md = wb.create_sheet("MetaData")
    ws_md.append(MD_COLS)
    for r in DATA:
        ws_md.append([
            r["index"], r["test_case_name"], r["meta_test_description"],
            r["meta_test_steps"], r["meta_impacted_registers"],
            r["validation_criteria"], r["headers"], r["defines"], r["arrays"]
        ])
    # Format both sheets
    for ws in [ws_tp, ws_md]:
        ws.freeze_panes = 'A2'
        for cell in ws[1]:
            cell.font = HEADER_FONT
            cell.fill = HEADER_FILL
            cell.alignment = WRAP
            cell.border = THIN_BORDER
        for row in ws.iter_rows(min_row=2):
            for cell in row:
                cell.alignment = WRAP
                cell.border = THIN_BORDER
        auto_width(ws)
    # Hide MetaData
    ws_md.sheet_state = 'veryHidden'
    # Save
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), FILENAME)
    wb.save(out)
    print(f"SUCCESS: {out} ({os.path.getsize(out)} bytes)")
    return out

if __name__ == '__main__':
    build()
